const request = $input.first()?.json ?? {};
const body = request.body ?? {};
const clean = (v) => v === null || v === undefined ? '' : String(v).trim();
const jobId = clean(body.job_id);
const returnUrl = clean(body.return_url) || 'https://n8n.proxy.shortcentral.com/webhook/member-list-mailout-report';
const isUuid = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(jobId);
if (!isUuid) {
  return [{ json: { ok: false, error: 'Invalid or missing job_id', job_id: jobId, return_url: returnUrl, sql: 'SELECT 0 AS deleted_jobs' } }];
}
const sql = `WITH del_recipients AS (DELETE FROM public.member_list_mailout_recipients WHERE job_id = '${jobId}'::uuid RETURNING id), del_job AS (DELETE FROM public.member_list_mailout_jobs WHERE id = '${jobId}'::uuid RETURNING id) SELECT (SELECT COUNT(*) FROM del_recipients)::int AS deleted_recipients, (SELECT COUNT(*) FROM del_job)::int AS deleted_jobs`;
return [{ json: { ok: true, job_id: jobId, return_url: returnUrl, sql } }];

const input = $('Build Delete SQL').first()?.json ?? {};
const result = $input.first()?.json ?? {};
const escapeHtml = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const returnUrl = input.return_url || 'https://n8n.proxy.shortcentral.com/webhook/member-list-mailout-report';
const ok = input.ok !== false;
const message = ok
  ? `Job deleted. Removed ${result.deleted_recipients ?? 0} recipient record(s) and ${result.deleted_jobs ?? 0} job record(s).`
  : `Delete failed: ${escapeHtml(input.error || 'Unknown error')}`;
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Delete Job</title><style>body{margin:0;padding:24px;background:#f0f4f8;font-family:Lato,Arial,sans-serif;color:#1f2937}.panel{max-width:600px;margin:0 auto;background:#fff;border:1px solid #d8e1ec;border-radius:16px;box-shadow:0 4px 24px rgba(15,23,42,.07);padding:28px}h1{margin:0 0 12px;font-size:22px;color:${ok?'#065f46':'#991b1b'}}.msg{padding:12px 16px;border-radius:12px;margin:12px 0;background:${ok?'#d1fae5':'#fee2e2'};color:${ok?'#065f46':'#991b1b'}}.btn{display:inline-flex;align-items:center;padding:10px 18px;border-radius:999px;font-weight:700;font-size:13px;text-decoration:none;color:#fff;background:linear-gradient(135deg,#0f766e,#115e59)}</style></head><body><div class="panel"><h1>${ok?'Job Deleted':'Delete Failed'}</h1><p class="msg">${escapeHtml(message)}</p><a class="btn" href="${escapeHtml(returnUrl)}">Back to Report</a></div></body></html>`;
return [{ json: { html } }];

